import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Install OrbySystems","description":"","frontmatter":{"title":"Install OrbySystems"},"headers":[],"relativePath":"docs/getting-started/install-orby.md","filePath":"docs/getting-started/install-orby.md","lastUpdated":1794290851000}'),s={name:"docs/getting-started/install-orby.md"};function n(d,e,i,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="install-orbysystems" tabindex="-1">Install OrbySystems <a class="header-anchor" href="#install-orbysystems" aria-label="Permalink to &quot;Install OrbySystems&quot;">​</a></h1><p>OrbySystems is a desktop app for macOS, Windows and Linux. Open the <a href="https://orbysystems.ai/downloads" target="_blank" rel="noreferrer">downloads page</a>, choose the build for your computer, and follow the <a href="/docs/overview/hardware-requirements">hardware guidance</a>. An account is not needed for local use.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Formats</th></tr></thead><tbody><tr><td>macOS</td><td><code>.dmg</code>, <code>.zip</code> for Apple silicon</td></tr><tr><td>Windows</td><td>Installer (<code>.exe</code>) or portable <code>.exe</code></td></tr><tr><td>Linux</td><td><code>.AppImage</code> or <code>.deb</code></td></tr></tbody></table><p>The download page recommends a build for your device and lists the published installers. If release details are unavailable, use its link to GitHub releases.</p><h2 id="what-happens-on-first-launch" tabindex="-1">What happens on first launch <a class="header-anchor" href="#what-happens-on-first-launch" aria-label="Permalink to &quot;What happens on first launch&quot;">​</a></h2><p>The app guides you through setup:</p><ol><li>Read the introduction and accept the terms.</li><li>Review reporting choices and choose local password protection and backup options.</li><li>Use the welcome screen to explore example data or start with your own statements.</li><li>Answer or skip the household questions. You can update these later in <strong>Settings → Profile</strong>.</li></ol><p>Keep your internet connection on while the initial model download finishes. Progress is shown during setup. If setup is interrupted, reopen the app and let it finish preparing the local service and model.</p><p>After setup, the built-in model can analyze documents already on your computer with Wi-Fi off. Downloads, enabled online tools, reporting and license checks are separate network activities.</p><h2 id="choosing-a-model" tabindex="-1">Choosing a model <a class="header-anchor" href="#choosing-a-model" aria-label="Permalink to &quot;Choosing a model&quot;">​</a></h2><p>OrbySystems recommends a built-in model for your computer&#39;s memory and downloads it locally. See <a href="/docs/overview/hardware-requirements">Hardware requirements</a> for model sizes and memory needs. You can change the model or connect an optional local server or cloud provider in <a href="/docs/settings/models">Settings → Models</a>.</p><h2 id="your-first-answer" tabindex="-1">Your first answer <a class="header-anchor" href="#your-first-answer" aria-label="Permalink to &quot;Your first answer&quot;">​</a></h2><p>Try the example household to see recipes and chat before adding personal data. When ready, <a href="/docs/getting-started/create-first-project">create a project</a> and <a href="/docs/getting-started/add-first-source">add statements</a>. You can also create an empty project and add files later.</p>',13)])])}const m=t(s,[["render",n]]);export{u as __pageData,m as default};
